input.proposed_solution:
Accept `page` (1-based) and `per_page` alongside the legacy parameters. If `offset` is given we use it as before; otherwise the offset is derived from the page number, with `page` defaulting to 1 so that default responses stay unchanged. `per_page` falls back to `limit` and goes through the existing clampLimit().

Patch (already applied in the repository snapshot):
```diff
--- a/src/api.js
+++ b/src/api.js
@@ -2,12 +2,13 @@
 import { clampLimit, paginate } from "./paginate.js";

 /**
- * GET /products?offset=&limit=
+ * GET /products?page=&per_page=   (legacy: ?offset=&limit=)
+ * `page` is 1-based.
  * @param {Array<{ id: number, name: string }>} products
  * @param {Record<string, string | undefined>} query
  */
 export function listProducts(products, query) {
-  const limit = clampLimit(query.limit);
-  const offset = Number(query.offset ?? 0);
-  return paginate(products, offset, limit);
+  const perPage = clampLimit(query.per_page ?? query.limit);
+  const offset = query.offset !== undefined ? Number(query.offset) : Number(query.page ?? 1) * perPage;
+  return paginate(products, offset, perPage);
 }
```
